-- Run only against the selected, empty PostgreSQL database.
-- Existing election tables stop the transaction; no data is deleted.
BEGIN;

DO $$
BEGIN
    IF to_regclass('public."Candidates"') IS NOT NULL OR to_regclass('public."Votes"') IS NOT NULL THEN
        RAISE EXCEPTION 'Candidates or Votes already exists; initialization stopped.';
    END IF;
END $$;

CREATE TABLE "Candidates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "Position" varchar(30) NOT NULL CHECK ("Position" IN
        ('President', 'VicePresident', 'Secretary', 'Treasurer', 'Auditor', 'PIO', 'PO', 'Representative')),
    "Grade" integer,
    CHECK (("Position" = 'Representative' AND "Grade" BETWEEN 8 AND 12)
        OR ("Position" <> 'Representative' AND "Grade" IS NULL))
);

CREATE TABLE "Votes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "VoterName" varchar(100) NOT NULL,
    "VoterIdNo" varchar(30) NOT NULL UNIQUE,
    "VoterGrade" integer NOT NULL CHECK ("VoterGrade" BETWEEN 7 AND 11),
    "PresidentId" integer REFERENCES "Candidates"("Id"),
    "VicePresidentId" integer REFERENCES "Candidates"("Id"),
    "SecretaryId" integer REFERENCES "Candidates"("Id"),
    "TreasurerId" integer REFERENCES "Candidates"("Id"),
    "AuditorId" integer REFERENCES "Candidates"("Id"),
    "PioId" integer REFERENCES "Candidates"("Id"),
    "PoId" integer REFERENCES "Candidates"("Id"),
    "RepresentativeId" integer REFERENCES "Candidates"("Id"),
    "Representative2Id" integer REFERENCES "Candidates"("Id"),
    "VotedAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMIT;
